insert into species (id, name, category, description, evolution_chain) values (1, 'bulbasaur', 'Seed Pokémon', 'While it is young, it uses the nutrients that are stored in the seed on its back in order to grow.', '{"id":1,"name":"bulbasaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1.png","evolvesTo":[{"id":2,"name":"ivysaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/2.png","evolvesTo":[{"id":3,"name":"venusaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/3.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (2, 'ivysaur', 'Seed Pokémon', 'Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.', '{"id":1,"name":"bulbasaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1.png","evolvesTo":[{"id":2,"name":"ivysaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/2.png","evolvesTo":[{"id":3,"name":"venusaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/3.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (3, 'venusaur', 'Seed Pokémon', 'A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.', '{"id":1,"name":"bulbasaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1.png","evolvesTo":[{"id":2,"name":"ivysaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/2.png","evolvesTo":[{"id":3,"name":"venusaur","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/3.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (4, 'charmander', 'Lizard Pokémon', 'From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.', '{"id":4,"name":"charmander","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/4.png","evolvesTo":[{"id":5,"name":"charmeleon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/5.png","evolvesTo":[{"id":6,"name":"charizard","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/6.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (5, 'charmeleon', 'Flame Pokémon', 'If it becomes agitated during battle, it spouts intense flames, incinerating its surroundings.', '{"id":4,"name":"charmander","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/4.png","evolvesTo":[{"id":5,"name":"charmeleon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/5.png","evolvesTo":[{"id":6,"name":"charizard","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/6.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (6, 'charizard', 'Flame Pokémon', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.', '{"id":4,"name":"charmander","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/4.png","evolvesTo":[{"id":5,"name":"charmeleon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/5.png","evolvesTo":[{"id":6,"name":"charizard","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/6.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (7, 'squirtle', 'Tiny Turtle Pokémon', 'When it feels threatened, it draws its limbs inside its shell and sprays water from its mouth.', '{"id":7,"name":"squirtle","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/7.png","evolvesTo":[{"id":8,"name":"wartortle","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/8.png","evolvesTo":[{"id":9,"name":"blastoise","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/9.png","evolvesTo":[]}]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (133, 'eevee', 'Evolution Pokémon', 'Harbors the potential to evolve into manifold forms. Within Eevee lies the key to the mysteries of Pokémon evolution—I''m certain of it.', '{"id":133,"name":"eevee","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/133.png","evolvesTo":[{"id":134,"name":"vaporeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/134.png","evolvesTo":[]},{"id":135,"name":"jolteon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/135.png","evolvesTo":[]},{"id":136,"name":"flareon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/136.png","evolvesTo":[]},{"id":196,"name":"espeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/196.png","evolvesTo":[]},{"id":197,"name":"umbreon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/197.png","evolvesTo":[]},{"id":470,"name":"leafeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/470.png","evolvesTo":[]},{"id":471,"name":"glaceon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/471.png","evolvesTo":[]},{"id":700,"name":"sylveon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/700.png","evolvesTo":[]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (134, 'vaporeon', 'Bubble Jet Pokémon', 'Tests show that its cells closely resemble water molecules, which perhaps explains its ability to conceal its form while submerged. I believe the origins of mermaid folklore lie with this Pokémon.', '{"id":133,"name":"eevee","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/133.png","evolvesTo":[{"id":134,"name":"vaporeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/134.png","evolvesTo":[]},{"id":135,"name":"jolteon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/135.png","evolvesTo":[]},{"id":136,"name":"flareon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/136.png","evolvesTo":[]},{"id":196,"name":"espeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/196.png","evolvesTo":[]},{"id":197,"name":"umbreon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/197.png","evolvesTo":[]},{"id":470,"name":"leafeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/470.png","evolvesTo":[]},{"id":471,"name":"glaceon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/471.png","evolvesTo":[]},{"id":700,"name":"sylveon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/700.png","evolvesTo":[]}]}'::jsonb);
insert into species (id, name, category, description, evolution_chain) values (135, 'jolteon', 'Lightning Pokémon', 'Bristles its fur into sharp, needlelike points when enraged. One can hear electricity crackle in its breath when it exhales.', '{"id":133,"name":"eevee","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/133.png","evolvesTo":[{"id":134,"name":"vaporeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/134.png","evolvesTo":[]},{"id":135,"name":"jolteon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/135.png","evolvesTo":[]},{"id":136,"name":"flareon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/136.png","evolvesTo":[]},{"id":196,"name":"espeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/196.png","evolvesTo":[]},{"id":197,"name":"umbreon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/197.png","evolvesTo":[]},{"id":470,"name":"leafeon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/470.png","evolvesTo":[]},{"id":471,"name":"glaceon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/471.png","evolvesTo":[]},{"id":700,"name":"sylveon","spriteUrl":"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/700.png","evolvesTo":[]}]}'::jsonb);
